String camelToSnake(String s) {
  final b = StringBuffer();
  for (var i = 0; i < s.length; i++) {
    final c = s[i];
    final up = c.toUpperCase() == c && c.toLowerCase() != c;
    if (up && i > 0) b.write('_');
    b.write(c.toLowerCase());
  }
  return b.toString();
}

