String snakeToCamel(String s) {
  final segs = s.split('_').where((x) => x.isNotEmpty).toList();
  if (segs.isEmpty) return '';
  final b = StringBuffer(segs.first.toLowerCase());
  for (final seg in segs.skip(1)) {
    b.write(seg[0].toUpperCase());
    b.write(seg.substring(1).toLowerCase());
  }
  return b.toString();
}

