String safeFilename(String s) {
  final replaced = s.replaceAll(RegExp(r'[^A-Za-z0-9._-]'), '_');
  final collapsed = replaced.replaceAll(RegExp('_+'), '_');
  return collapsed.replaceAll(RegExp('^_+|_+\$'), '');
}

