String runLengthEncode(String s) {
  if (s.isEmpty) return '';
  final b = StringBuffer();
  var cur = s[0];
  var n = 1;
  for (var i = 1; i < s.length; i++) {
    if (s[i] == cur) {
      n++;
    } else {
      b.write('$cur$n');
      cur = s[i];
      n = 1;
    }
  }
  b.write('$cur$n');
  return b.toString();
}

