String wordWrap(String s, int w) {
  final n = s.replaceAll(RegExp('[ \t]+'), ' ').trim();
  if (n.isEmpty) return '';
  final words = n.split(' ');
  final lines = <String>[];
  var line = '';
  for (final word in words) {
    if (word.length > w) {
      if (line.isNotEmpty) lines.add(line);
      lines.add(word);
      line = '';
      continue;
    }
    final add = line.isEmpty ? word.length : line.length + 1 + word.length;
    if (add <= w) {
      line = line.isEmpty ? word : '$line $word';
    } else {
      lines.add(line);
      line = word;
    }
  }
  if (line.isNotEmpty) lines.add(line);
  return lines.join('\n');
}

tasks.verify_test:
import 'package:test/test.dart';
import 'package:lb_sandbox/word_wrap.dart';

void main() {
  test('word_wrap', () {
    expect(wordWrap('', 5), '');
    expect(wordWrap('one', 3), 'one');
    expect(wordWrap('aaa bb c', 3), 'aaa\nbb\nc');
    expect(wordWrap('short', 2), 'short');
    expect(wordWrap('the quick brown fox', 9), 'the quick\nbrown fox');
  });
